import fs from 'node:fs'
import path from 'node:path'

import { findEnginesBuiltInInitializers } from './examplesEngineHooks.ts'

// Tools for keeping examples-site prose linked to the autogenerated JBrowse docs
// (jbrowse.org/jb2/docs/...). Two jobs:
//   - validate that every doc link in the prose still resolves to a real
//     generated page (catches renames/removals like the old WebWorkerRpcDriver)
//   - suggest links: scan an example's config `type: '...'` values and map each
//     to its generated config/model page, so adding "Reference" links is
//     mechanical instead of from-memory
//
// The mapping is exact and deterministic: a config `type` (e.g. `BigWigAdapter`)
// becomes the lowercased Docusaurus `id` of its generated page
// (`config/bigwigadapter`). No heuristics.

export interface DocPage {
  // lowercased Docusaurus id / url slug, e.g. 'bigwigadapter'
  id: string
  // section under /jb2/docs/, '' for top-level pages
  section: string
  // full url path, e.g. 'config/bigwigadapter' or 'cli'
  urlPath: string
}

// sections under website/docs whose pages are valid link targets: the
// autogenerated reference (config/models) plus hand-written guide/tutorial dirs
// that prose commonly links into
const SECTIONS = [
  'config',
  'models',
  'config_guides',
  'user_guides',
  'developer_guides',
  'tutorials',
]

// generated reference pages live under these sections and key off the type name
const TYPE_SECTIONS = new Set(['config', 'models'])

// a type used in more than this fraction of example files is boilerplate
// (assembly/sequence/feature-track setup repeated everywhere) — linking it in
// every page is noise, so it's dropped from suggestions by default
const DEFAULT_COMMON_TYPE_RATIO = 0.5

const DOCS_BASE = 'https://jbrowse.org/jb2/docs/'

// section landing pages and stable hand-written top-level guides that have no
// own .md basename match but are always valid link targets
const KNOWN_INDEX_SLUGS = new Set(['config', 'models', 'config_guide'])

function readFirstId(file: string): string | undefined {
  const head = fs.readFileSync(file, 'utf8').slice(0, 600)
  const m = /^id:\s*(\S+)/m.exec(head)
  return m ? m[1] : undefined
}

function listMarkdown(dir: string): string[] {
  return fs.existsSync(dir)
    ? fs.readdirSync(dir).filter(f => f.endsWith('.md'))
    : []
}

// Build the set of valid generated doc pages from a checked-out `website/docs`
// tree. The url id is the page's `id:` frontmatter when present (autogenerated
// pages set it), else the lowercased filename (hand-written guides).
export function buildDocIndex(referenceDir: string): DocPage[] {
  const pages: DocPage[] = []
  for (const section of SECTIONS) {
    const dir = path.join(referenceDir, section)
    for (const file of listMarkdown(dir)) {
      const id =
        readFirstId(path.join(dir, file)) ??
        path.basename(file, '.md').toLowerCase()
      pages.push({ id, section, urlPath: `${section}/${id}` })
    }
  }
  for (const file of listMarkdown(referenceDir)) {
    const id =
      readFirstId(path.join(referenceDir, file)) ??
      path.basename(file, '.md').toLowerCase()
    pages.push({ id, section: '', urlPath: id })
  }
  return pages
}

function listFilesRecursive(dir: string, exts: string[]): string[] {
  const out: string[] = []
  const walk = (d: string) => {
    for (const entry of fs.readdirSync(d, { withFileTypes: true })) {
      const full = path.join(d, entry.name)
      if (entry.isDirectory()) {
        walk(full)
      } else if (exts.some(e => entry.name.endsWith(e))) {
        out.push(full)
      }
    }
  }
  if (fs.existsSync(dir)) {
    walk(dir)
  }
  return out
}

export interface BrokenLink {
  file: string
  url: string
  urlPath: string
}

// Scan content files for jbrowse.org doc links and return those whose target
// page is missing from the generated docs. Anchors and trailing slashes are
// ignored. Returns [] when everything resolves.
export function findBrokenDocLinks({
  contentDirs,
  referenceDir,
}: {
  contentDirs: string[]
  referenceDir: string
}): BrokenLink[] {
  const valid = new Set(buildDocIndex(referenceDir).map(p => p.urlPath))
  for (const slug of KNOWN_INDEX_SLUGS) {
    valid.add(slug)
  }
  const broken: BrokenLink[] = []
  const linkRe = /https:\/\/jbrowse\.org\/jb2\/docs\/([A-Za-z0-9_/]+)/g
  const files = contentDirs.flatMap(d =>
    listFilesRecursive(d, ['.md', '.astro']),
  )
  for (const file of files) {
    const text = fs.readFileSync(file, 'utf8')
    for (const m of text.matchAll(linkRe)) {
      const urlPath = m[1]!.replace(/\/$/, '')
      if (!valid.has(urlPath)) {
        broken.push({ file, url: m[0], urlPath })
      }
    }
  }
  return broken
}

export interface BrokenCrossLink {
  file: string
  url: string
  reason: string
}

// Scan content files for the site-internal cross-links the example docs use to
// point at each other (`../<page-slug>/#<section-slug>`) and return the ones
// that no longer resolve. These break silently whenever a page is renamed or a
// section is moved between pages, which the outbound jbrowse.org check can't
// see. `pages` is the site's own examples.ts page list.
export function findBrokenCrossLinks({
  contentDirs,
  pages,
}: {
  contentDirs: string[]
  pages: { slug: string; sections: { slug: string }[] }[]
}): BrokenCrossLink[] {
  const pageSlugs = new Set(pages.map(p => p.slug))
  // a section anchor is only valid on the page that actually holds it
  const sectionsByPage = new Map(
    pages.map(p => [p.slug, new Set(p.sections.map(s => s.slug))]),
  )
  const broken: BrokenCrossLink[] = []
  // anchored on markdown `](…)` / html `href="…"` so it can't fire on the
  // `../examples/Foo.tsx` import specifiers in .astro page files
  const linkRe =
    /(?:\]\(|href=")\.\.\/([A-Za-z0-9-]+)\/(#([A-Za-z0-9-]+))?(?=[)"])/g
  const files = contentDirs.flatMap(d =>
    listFilesRecursive(d, ['.md', '.astro']),
  )
  for (const file of files) {
    const text = fs.readFileSync(file, 'utf8')
    for (const m of text.matchAll(linkRe)) {
      const [match, page, , anchor] = m
      if (!page) {
        continue
      }
      const url = match.replace(/^(\]\(|href=")/, '')
      if (!pageSlugs.has(page)) {
        broken.push({ file, url, reason: `no page "${page}"` })
      } else if (anchor && !sectionsByPage.get(page)?.has(anchor)) {
        broken.push({
          file,
          url,
          reason: `page "${page}" has no section "${anchor}"`,
        })
      }
    }
  }
  return broken
}

export interface MissingDoc {
  // the section slug with no prose file
  slug: string
  // the page that holds it, for the error message
  page: string
  // the src/docs/<slug>.md path that should exist
  expected: string
}

// Every section renders `src/docs/<section-slug>.md` above its demo, and
// ExampleSection renders nothing at all when the file is absent. So a page can
// ship with a title, a one-line lead and several hundred lines of source and no
// explanation, and nothing says so — which is how the build-your-own site's own
// lead page went out with no prose. Cheap to check, invisible otherwise.
//
// Orphans are reported too: a doc whose section was renamed stops being
// rendered and silently becomes dead prose.
export function findMissingDocs({
  docsDir,
  pages,
}: {
  docsDir: string
  pages: { slug: string; sections: { slug: string }[] }[]
}): { missing: MissingDoc[]; orphans: string[] } {
  const present = new Set(
    listMarkdown(docsDir).map(f => f.replace(/\.md$/, '')),
  )
  const missing = pages.flatMap(p =>
    p.sections
      .filter(s => !present.has(s.slug))
      .map(s => ({
        slug: s.slug,
        page: p.slug,
        expected: path.join(docsDir, `${s.slug}.md`),
      })),
  )
  const sections = new Set(pages.flatMap(p => p.sections.map(s => s.slug)))
  return { missing, orphans: [...present].filter(d => !sections.has(d)) }
}

// An examples-site page is a live demo plus its own source; the prose exists to
// name the API and flag the gotchas, not to explain the demo at length. Left
// unchecked it grows back — these pages had drifted to 800-word essays with
// "Where to stop" sections before this cap existed.
//
// The cap was 500/350 and every doc was rewritten against 300/200, because a
// doc allowed 500 words reliably spends them: on a demo the reader can just
// look at, on a paragraph restating the source rendered directly below it, and
// on a closing pile of reference links. 300 words is roughly a screen, which is
// the right budget for an annotation on a demo. A page needing more than that
// is a tutorial on website/docs with a link to it from here, not a longer doc.
const DEFAULT_MAX_DOC_WORDS = 300
// gallery-card and "On this page" descriptions, where one line is the format
const DEFAULT_MAX_DESCRIPTION_CHARS = 160
// advisory only — printed, never fatal, so the trend is visible before the cap
const LONG_DOC_WORDS = 200

export interface LongProse {
  // what to name in the error, e.g. 'src/docs/pan-and-zoom.md' or a page slug
  what: string
  size: number
  limit: number
}

function wordCount(text: string): number {
  return text.split(/\s+/).filter(Boolean).length
}

// Docs over `maxWords` (fatal) and, separately, the ones merely getting long
// (advisory). Fenced code blocks are excluded: a page whose length is a config
// example is doing its job, and counting it would push prose out to make room.
export function findLongDocs({
  docsDir,
  maxWords = DEFAULT_MAX_DOC_WORDS,
  longWords = LONG_DOC_WORDS,
}: {
  docsDir: string
  maxWords?: number
  longWords?: number
}): { over: LongProse[]; long: LongProse[] } {
  const sized = listMarkdown(docsDir).map(f => ({
    what: `src/docs/${f}`,
    size: wordCount(
      fs
        .readFileSync(path.join(docsDir, f), 'utf8')
        .replaceAll(/^```[\s\S]*?^```/gm, ''),
    ),
    limit: maxWords,
  }))
  return splitByLimit(sized, maxWords, longWords)
}

function splitByLimit(
  sized: LongProse[],
  maxWords: number,
  longWords: number,
): { over: LongProse[]; long: LongProse[] } {
  return {
    over: sized.filter(d => d.size > maxWords).sort((a, b) => b.size - a.size),
    long: sized
      .filter(d => d.size > longWords && d.size <= maxWords)
      .sort((a, b) => b.size - a.size),
  }
}

// The same cap over the prose written directly in `src/pages/*.astro`, which is
// almost entirely the landing page — the example pages are imports and
// `<Section>` tags. It needs its own pass because `findLongDocs` only ever saw
// `src/docs/*.md`, and a landing page is where a reader starts: LGV's had grown
// to 289 words of install-and-bundler notes restating `website/docs` while the
// docs beside it were held to 300, because nothing counted it.
//
// Stripped, in order: frontmatter, `<style>`/`<script>` blocks, `{…}`
// expressions (which is how `<Code code={…}/>` and every comment leave), then
// tags. Undercounting is the right failure here — the cap should fire on prose
// someone typed, not on markup.
export function findLongPages({
  pagesDir,
  maxWords = DEFAULT_MAX_DOC_WORDS,
  longWords = LONG_DOC_WORDS,
}: {
  pagesDir: string
  maxWords?: number
  longWords?: number
}): { over: LongProse[]; long: LongProse[] } {
  const sized = listFilesRecursive(pagesDir, ['.astro']).map(file => ({
    what: `src/pages/${path.relative(pagesDir, file)}`,
    size: wordCount(
      fs
        .readFileSync(file, 'utf8')
        .replace(/^---[\s\S]*?^---/m, '')
        .replaceAll(/<(style|script)[\s\S]*?<\/\1>/g, '')
        .replaceAll(/\{[\s\S]*?\}/g, ' ')
        .replaceAll(/<[^>]+>/g, ' '),
    ),
    limit: maxWords,
  }))
  return splitByLimit(sized, maxWords, longWords)
}

// Page and section descriptions render as a single line on a gallery card or in
// the "On this page" card, so a description that runs to three clauses is
// already the wrong shape for where it appears.
export function findLongDescriptions({
  pages,
  maxChars = DEFAULT_MAX_DESCRIPTION_CHARS,
}: {
  pages: {
    slug: string
    description?: string
    sections: { slug: string; description?: string }[]
  }[]
  maxChars?: number
}): LongProse[] {
  const all = pages.flatMap(p => [
    { what: `page "${p.slug}"`, text: p.description },
    ...p.sections.map(s => ({
      what: `section "${s.slug}"`,
      text: s.description,
    })),
  ])
  return all
    .filter(d => (d.text?.length ?? 0) > maxChars)
    .map(d => ({ what: d.what, size: d.text!.length, limit: maxChars }))
    .sort((a, b) => b.size - a.size)
}

export interface DocSuggestion {
  // the config `type` value found, e.g. 'BigWigAdapter'
  term: string
  // matching generated pages (config and/or model), as full urls
  urls: string[]
  // the example files using this type, as context for where to put the link
  files: string[]
}

// Scan example source for config `type: '...'` values and map each to the
// generated reference page(s) for that type. Output is advisory — a maintainer
// pastes the urls into the example's doc prose. Only types that actually have a
// generated page are returned (so plugin/test-only types are skipped). When
// `contentDirs` is given, types whose page url already appears anywhere in that
// prose are dropped, so the output is only the links still worth adding.
// Boilerplate types used across most examples (assembly/sequence setup) are
// dropped via `commonTypeRatio`.
//
// **One suggestion per type, not per (file, type).** `existing` is the whole
// site's prose joined, so one link anywhere satisfies a type everywhere — which
// makes adding it a single action, and emitting a line per file that uses it
// just multiplies one action by its callers. react-app printed 57 lines for 16
// types that way, and an advisory that long is one nobody reads, which costs
// you the few genuinely missing links buried in it.
export function suggestDocLinks({
  exampleDirs,
  referenceDir,
  contentDirs,
  commonTypeRatio = DEFAULT_COMMON_TYPE_RATIO,
}: {
  exampleDirs: string[]
  referenceDir: string
  contentDirs?: string[]
  commonTypeRatio?: number
}): DocSuggestion[] {
  const existing = contentDirs
    ? contentDirs
        .flatMap(d => listFilesRecursive(d, ['.md', '.astro']))
        .map(f => fs.readFileSync(f, 'utf8'))
        .join('\n')
    : ''
  const byIdSection = new Map<string, Set<string>>()
  for (const page of buildDocIndex(referenceDir)) {
    if (TYPE_SECTIONS.has(page.section)) {
      const set = byIdSection.get(page.id) ?? new Set<string>()
      set.add(page.section)
      byIdSection.set(page.id, set)
    }
  }
  const typeRe = /type:\s*'([A-Z][A-Za-z0-9]+)'/g
  const files = exampleDirs.flatMap(d => listFilesRecursive(d, ['.tsx', '.ts']))

  // first pass: the distinct documented types per file, and how many files use
  // each (to identify boilerplate)
  const perFileTerms = new Map<string, string[]>()
  const fileCount = new Map<string, number>()
  for (const file of files) {
    const text = fs.readFileSync(file, 'utf8')
    const terms = [
      ...new Set(
        [...text.matchAll(typeRe)]
          .map(m => m[1]!)
          .filter(term => byIdSection.has(term.toLowerCase())),
      ),
    ]
    perFileTerms.set(file, terms)
    for (const term of terms) {
      fileCount.set(term, (fileCount.get(term) ?? 0) + 1)
    }
  }
  const commonThreshold = files.length * commonTypeRatio

  const filesByTerm = new Map<string, string[]>()
  for (const [file, terms] of perFileTerms) {
    for (const term of terms) {
      filesByTerm.set(term, [...(filesByTerm.get(term) ?? []), file])
    }
  }

  const suggestions: DocSuggestion[] = []
  for (const [term, termFiles] of filesByTerm) {
    const id = term.toLowerCase()
    const urls = [...byIdSection.get(id)!]
      .sort()
      .map(s => `${DOCS_BASE}${s}/${id}/`)
    const allLinked = urls.every(u => existing.includes(u))
    // `>=`, not `>`: at exactly the ratio a type is as boilerplate as one a
    // file over it. LinearGenomeView sat on 11 of react-app's 22 examples and
    // survived a `>` on the nose, which is the least useful suggestion the
    // scan can produce — it is in nearly every example because it is the view.
    const isCommon = (fileCount.get(term) ?? 0) >= commonThreshold
    if (!isCommon && !(contentDirs && allLinked)) {
      suggestions.push({ term, urls, files: termFiles.sort() })
    }
  }
  return suggestions.sort((a, b) => b.files.length - a.files.length)
}

// The whole `pnpm check-links` run for one examples-site: every check above,
// printed and reduced to an exit code. Each site's scripts/check-doc-links.mjs
// was a byte-identical 122-line copy of this — the file already carried a
// comment saying the shared impl belongs here, and this is the rest of it
// arriving. The two things that genuinely differ per site, its own `pages` list
// and where it sits on disk, are the arguments.
//
// Returns the failure count; the caller exits on it, so this stays testable.
export function runExamplesSiteChecks({
  root,
  pages,
  referenceDir,
  log = console.log,
}: {
  // the examples-site directory, i.e. the one holding src/ and scripts/
  root: string
  pages: {
    slug: string
    description?: string
    sections: { slug: string; description?: string }[]
  }[]
  referenceDir: string
  log?: (message: string) => void
}): number {
  const src = path.join(root, 'src')
  const docsDir = path.join(src, 'docs')
  const rel = (f: string) => path.relative(root, f)
  const contentDirs = [docsDir, path.join(src, 'pages')]

  const broken = findBrokenDocLinks({ contentDirs, referenceDir })
  for (const b of broken) {
    log(`BROKEN ${b.url}\n       in ${rel(b.file)}`)
  }

  const brokenCross = findBrokenCrossLinks({ contentDirs, pages })
  for (const b of brokenCross) {
    log(`BROKEN ${b.url}  (${b.reason})\n       in ${rel(b.file)}`)
  }

  const { missing, orphans } = findMissingDocs({ docsDir, pages })
  for (const m of missing) {
    log(
      `NO DOC ${m.slug}  (section of page "${m.page}")\n` +
        `       expected ${rel(m.expected)}`,
    )
  }
  for (const o of orphans) {
    log(`ORPHAN src/docs/${o}.md  (no section with that slug renders it)`)
  }

  const { over: longDocs, long: gettingLong } = findLongDocs({ docsDir })
  // the same cap over prose written straight into a page — in practice the
  // landing page, which findLongDocs never saw
  const { over: longPages, long: pagesGettingLong } = findLongPages({
    pagesDir: path.join(src, 'pages'),
  })
  for (const d of [...longDocs, ...longPages]) {
    log(`TOO LONG ${d.what}  ${d.size} words (max ${d.limit})`)
  }

  const longDescriptions = findLongDescriptions({ pages })
  for (const d of longDescriptions) {
    log(`TOO LONG description of ${d.what}  ${d.size} chars (max ${d.limit})`)
  }

  const suggestions = suggestDocLinks({
    exampleDirs: [path.join(src, 'examples')],
    referenceDir,
    contentDirs,
  })
  if (suggestions.length) {
    log('\nSuggested reference links (config types not yet linked):')
    for (const s of suggestions) {
      // one line per type — the link only has to land in one doc to count. The
      // files are context for which doc that should be, so show a couple and
      // count the rest rather than listing every caller.
      const shown = s.files.slice(0, 2).map(f => path.basename(f))
      const more = s.files.length - shown.length
      const where = more > 0 ? `${shown.join(', ')} +${more}` : shown.join(', ')
      log(`  ${s.term}  (${where})`)
      for (const u of s.urls) {
        log(`      ${u}`)
      }
    }
  }

  // Not a link check, and it runs here because this is the one entry point all
  // four sites already call. See examplesEngineHooks.ts for why a published
  // helper was not enough on its own.
  const engines = findEnginesBuiltInInitializers([path.join(src, 'examples')])
  for (const e of engines) {
    log(
      `ENGINE IN INITIALIZER ${rel(e.file)}:${e.line}\n` +
        `       ${e.text}\n` +
        '       StrictMode double-invokes this and discards the second engine,\n' +
        "       which then has nothing holding it. Use the product's\n" +
        '       useCreateViewState, or useCreateOnce where that cannot fit.',
    )
  }

  const advisory = [...gettingLong, ...pagesGettingLong].sort(
    (a, b) => b.size - a.size,
  )
  if (advisory.length) {
    log('\nGetting long (advisory):')
    for (const d of advisory) {
      log(`  ${d.what}  ${d.size} words`)
    }
  }

  const tooLong = longDocs.length + longPages.length + longDescriptions.length
  log(
    `\n${broken.length + brokenCross.length} broken link(s), ` +
      `${missing.length} missing doc(s), ${orphans.length} orphan(s), ` +
      `${tooLong} over-long prose, ${engines.length} engine(s) in an ` +
      `initializer, ${suggestions.length} suggestion(s)`,
  )
  return (
    broken.length +
    brokenCross.length +
    missing.length +
    tooLong +
    engines.length
  )
}
